# Generated by test-lab — blind adversarial evaluation
"""The spine contract must stay executable data, and the compiler honest.

These began as tests for a hand-rolled orchestrator I wrote and then deleted:
Tau's generic DAG runner already does dependency ordering, receipt gating, and
fail-closed stops, so a second executor here was the same bespoking this work
exists to prevent. What survives are the guarantees that are still ours -- the
contract's shape, and what the compiler emits.
"""
from __future__ import annotations

import sys
from pathlib import Path

import yaml

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "scripts"))

import build_dream_dag as bdd  # noqa: E402

CONTRACT = ROOT / "contracts" / "dream_spine.v1.yaml"


def _spine() -> dict:
    return yaml.safe_load(CONTRACT.read_text(encoding="utf-8"))


def test_the_spine_is_data_not_welded_to_a_run_record():
    """The 42-step taxonomy was unusable because it lived inside an audit script
    with a hardcoded RUN_ID and REVISION_ID. A definition fused to one run
    cannot be executed, diffed, or compiled."""
    spine = _spine()
    assert spine["schema"] == "persona_dream.dream_spine.v1"
    src = (ROOT / "scripts" / "build_dream_dag.py").read_text(encoding="utf-8")
    assert "REVISION_ID" not in src and "RUN_ID = " not in src


def test_the_spine_terminates_where_it_says_it_does():
    spine = _spine()
    assert [s["id"] for s in spine["steps"]][-1] == spine["terminates_at"]
    assert spine["terminates_at"] == "chatterbox_conversation"


def test_every_step_declares_artifacts_and_both_claim_directions():
    """A step that only advertises what it proves invites over-reading, and one
    that declares no artifacts cannot be checked at all."""
    for step in _spine()["steps"]:
        assert step.get("produces"), f"{step['id']} declares no artifacts"
        assert step.get("proves") and step.get("does_not_prove"), step["id"]


def test_each_step_declares_its_own_run_dir_flag():
    """They genuinely disagree -- --run-root, --run-dir, --cycles-dir, none.
    Assuming one flag is how an orchestrator mis-invokes a step and then reports
    the wrong reason for the failure."""
    for step in _spine()["steps"]:
        assert "run_dir_arg" in step, f"{step['id']} does not declare its flag"


def test_the_compiled_spec_is_strictly_sequential():
    """The journal cannot precede the dream, and conversation stays terminal."""
    spec = bdd.build_spec(contract=CONTRACT, run_dir=Path("/tmp/x"),
                          run_id="t", persona="embry", cycle_id="c1", idea="",
                          timeout_seconds=60)
    nodes = spec["nodes"]
    assert nodes[0]["depends_on"] == []
    for earlier, later in zip(nodes, nodes[1:]):
        assert later["depends_on"] == [earlier["node_id"]]


def test_goal_hash_reproduces_taus_canonical_encoding():
    """Tau recomputes this and refuses the spec on mismatch, so the encoding is
    not ours to choose. json.dumps defaults to ensure_ascii=True, which diverges
    silently the first time a summary carries a non-ASCII character."""
    import hashlib
    import json

    goal = {"goal_id": "g", "goal_version": 1, "summary": "caf\u00e9",
            "completion_criteria": ["x"]}
    expected = "sha256:" + hashlib.sha256(json.dumps(
        goal, sort_keys=True, separators=(",", ":"), ensure_ascii=False,
    ).encode("utf-8")).hexdigest()
    assert bdd._goal_hash(goal) == expected


def test_an_absent_idea_drops_the_flag_rather_than_passing_it_empty():
    """Tau rejects empty argv items, and an empty --about means something
    different to the step than omitting it."""
    with_idea = bdd.build_spec(contract=CONTRACT, run_dir=Path("/tmp/x"),
                               run_id="t", persona="embry", cycle_id="c1",
                               idea="kai", timeout_seconds=60)
    without = bdd.build_spec(contract=CONTRACT, run_dir=Path("/tmp/x"),
                             run_id="t", persona="embry", cycle_id="c1",
                             idea="", timeout_seconds=60)
    assert "--step-arg=--about" in with_idea["nodes"][0]["command"]
    assert "--step-arg=--about" not in without["nodes"][0]["command"]
    assert "" not in without["nodes"][0]["command"]
